import type { ExportSpec, ManifestEntry } from "../manifest-types";

/** Owner C — services, repositories and background jobs.
 *
 *  Repositories own SQL and MUST filter by `orgId` on every query and by
 *  `archived_at` through `@/lib/soft-delete`. Services own business rules and
 *  are the only layer allowed to call `assertCan` and `emit`. Jobs run outside
 *  the request lifecycle and re-derive their own `Actor`. */

const fn = (name: string, signature: string): ExportSpec => ({
  name,
  kind: "function",
  signature,
});

const type = (name: string, signature: string): ExportSpec => ({
  name,
  kind: "type",
  signature,
});
---
import type { ManifestEntry } from "../manifest-types";

/** Owner B — feature components and React hooks. These compose `src/components/ui`,
 *  read the frozen types, and are the UI-side consumers of `can()` and the
 *  feature flags. They never touch `src/server/**` directly; data arrives as props
 *  from a Server Component, or through a Server Action passed in. */

type DomainSpec = [
  file: string,
  component: string,
  props: string,
  responsibility: string,
  mustUse?: string[],
  client?: boolean,
];

const DOMAIN: DomainSpec[] = [
  ["issue/issue-card", "IssueCard", "{ issue: Issue; assignee?: User | null; labels?: readonly IssueLabel[]; href: string; compact?: boolean }", "Compact issue summary tile used by lists and the board."],
